using namespace Eigen;

// Newmark-beta average acceleration integrator
std::vector<Vector3d> integrate(const Matrix3d& K, const Matrix3d& M,
                                 Vector3d u, Vector3d v, Vector3d a,
                                 double dt, int nsteps, int stride) {
    const double beta = 0.25, gamma = 0.5;
    Matrix3d Keff = M / (beta * dt * dt) + K;
    Matrix3d KeffInv = Keff.inverse();
    std::vector<Vector3d> out;
    out.push_back(u);
    for (int n = 0; n < nsteps; ++n) {
        Vector3d rhs = M * (u / (beta * dt * dt) + v / (beta * dt) + (1.0 / (2 * beta) - 1) * a);
        Vector3d un = KeffInv * rhs;
        Vector3d an = (un - u) / (beta * dt * dt) - v / (beta * dt) - (1.0 / (2 * beta) - 1) * a;
        Vector3d vn = v + dt * ((1 - gamma) * a + gamma * an);
        u = un; v = vn; a = an;
        if ((n + 1) % stride == 0) out.push_back(u);
    }
    return out;
}

